for(let d=-9;d<=29;d++){const y=sy(d);for(const x of[53,325,575,847])svg+=`<line x1="${x-5}" x2="${x+5}" y1="${y}" y2="${y}" stroke="#c8d8bd" stroke-opacity=".24" stroke-width="2"/>`;}
